class Solution:
    def badSensor(self, sensor1, sensor2):
        n = len(sensor1)

        def faulty(x, y):
            for d in range(n):
                ok = x[-1] != y[d]
                for t in range(d):
                    if x[t] != y[t]:
                        ok = False
                        break
                if not ok:
                    continue
                for t in range(d, n - 1):
                    if x[t] != y[t + 1]:
                        ok = False
                        break
                if ok:
                    return True
            return False

        f1, f2 = faulty(sensor1, sensor2), faulty(sensor2, sensor1)
        if f1 and not f2:
            return 1
        if f2 and not f1:
            return 2
        return -1

