class Solution {
public:
    bool faulty(vector<int>& x, vector<int>& y) {
        int n = x.size();
        for (int d = 0; d < n; d++) {
            bool ok = x[n - 1] != y[d];
            for (int t = 0; ok && t < d; t++) ok = x[t] == y[t];
            for (int t = d; ok && t < n - 1; t++) ok = x[t] == y[t + 1];
            if (ok) return true;
        }
        return false;
    }

    int badSensor(vector<int>& sensor1, vector<int>& sensor2) {
        bool f1 = faulty(sensor1, sensor2), f2 = faulty(sensor2, sensor1);
        if (f1 && !f2) return 1;
        if (f2 && !f1) return 2;
        return -1;
    }
};

